package com.orderflow.delivery.security;import java.util.*;import org.springframework.security.oauth2.jwt.Jwt;public record RequestIdentity(UUID userId,boolean admin,boolean deliveryAgent){public static RequestIdentity from(Jwt j){List<String>r=j.getClaimAsStringList("roles");return new RequestIdentity(UUID.fromString(j.getSubject()),r!=null&&r.contains("ADMIN"),r!=null&&r.contains("DELIVERY_AGENT"));}}
